bool init_freelist_state(union freelist_init_state *state,
                         struct kmem_cache *cachep,
                         unsigned int count) {
    int seed = rand();
    bool has_precomputed = false;

    if (cachep->random_sequence == NULL) {
        // No pre-computed sequence, seed the state manually
        state->random_state = seed;
        state->count = count;
        has_precomputed = false;
    } else {
        // Use pre-computed sequence
        state->sequence = cachep->random_sequence;
        state->count = count;
        // Pick a random position in the list based on the seed
        state->current_index = seed % count;
        has_precomputed = true;
    }

    return has_precomputed;
}

